public class InnerThemeTypographyFactory(Action<Humidifier.QuickSight.ThemeTypes.Typography> factoryAction = null) : SubResourceFactory<Humidifier.QuickSight.ThemeTypes.Typography>
{

    internal InnerThemeVisualTitleFontConfigurationFactory VisualTitleFontConfigurationFactory { get; set; }

    internal InnerThemeVisualSubtitleFontConfigurationFactory VisualSubtitleFontConfigurationFactory { get; set; }

    internal InnerThemeFontConfigurationFactory LegendValueFontConfigurationFactory { get; set; }

    internal InnerThemeFontConfigurationFactory AxisTitleFontConfigurationFactory { get; set; }

    internal InnerThemeFontConfigurationFactory AxisLabelFontConfigurationFactory { get; set; }

    internal InnerThemeFontConfigurationFactory LegendTitleFontConfigurationFactory { get; set; }

    internal InnerThemeFontConfigurationFactory DataLabelFontConfigurationFactory { get; set; }

    protected override Humidifier.QuickSight.ThemeTypes.Typography Create()
    {
        var typographyResult = CreateTypography();
        factoryAction?.Invoke(typographyResult);

        return typographyResult;
    }

    private Humidifier.QuickSight.ThemeTypes.Typography CreateTypography()
    {
        var typographyResult = new Humidifier.QuickSight.ThemeTypes.Typography();

        return typographyResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.ThemeTypes.Typography result)
    {
        base.CreateChildren(result);

        result.VisualTitleFontConfiguration ??= VisualTitleFontConfigurationFactory?.Build();
        result.VisualSubtitleFontConfiguration ??= VisualSubtitleFontConfigurationFactory?.Build();
        result.LegendValueFontConfiguration ??= LegendValueFontConfigurationFactory?.Build();
        result.AxisTitleFontConfiguration ??= AxisTitleFontConfigurationFactory?.Build();
        result.AxisLabelFontConfiguration ??= AxisLabelFontConfigurationFactory?.Build();
        result.LegendTitleFontConfiguration ??= LegendTitleFontConfigurationFactory?.Build();
        result.DataLabelFontConfiguration ??= DataLabelFontConfigurationFactory?.Build();
    }

} // End Of Class

